package web

import (
	"bytes"
	"encoding/json"
	"image/png"
	"net/http"
	"os"
	"testing"
	"time"
)

// TestBrowserQRReceiver (manual/assisted): set DS_QR_LISTEN=127.0.0.1:18999,
// then let the browser POST {png: dataURL-bytes(base64-decoded), url} from
// the share dialog. The PNG generated by the real browser canvas is decoded
// and compared with the link shown in the dialog.
func TestBrowserQRReceiver(t *testing.T) {
	addr := os.Getenv("DS_QR_LISTEN")
	if addr == "" {
		t.Skip("set DS_QR_LISTEN to run")
	}
	done := make(chan string, 1)
	srv := &http.Server{Addr: addr, Handler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "*")
		if r.Method == http.MethodOptions {
			return
		}
		var in struct {
			PNG []byte `json:"png"`
			URL string `json:"url"`
		}
		json.NewDecoder(r.Body).Decode(&in)
		img, err := png.Decode(bytes.NewReader(in.PNG))
		res := "FAIL: png decode"
		if err == nil {
			got, err := DecodeQR(img)
			switch {
			case err != nil:
				res = "FAIL: qr decode: " + err.Error()
			case got == in.URL:
				res = "PASS: browser PNG decodes to exactly the shared link"
			default:
				res = "FAIL: decoded text differs"
			}
		}
		w.Write([]byte(res))
		done <- res
	})}
	go srv.ListenAndServe()
	defer srv.Close()
	select {
	case res := <-done:
		t.Log(res)
		if res[:4] != "PASS" {
			t.Fatal(res)
		}
	case <-time.After(3 * time.Minute):
		t.Fatal("no browser upload")
	}
}
